WITH latest_match AS (SELECT s.id, s.store_id, s.status, s.channel, s.amount, s.shipping_fee, top1.shipment_cost, top1.carrier FROM orders s LEFT JOIN LATERAL (SELECT c.cost AS shipment_cost, c.carrier FROM shipments c WHERE c.order_id = s.id AND c.delivered_date <= s.order_date ORDER BY c.delivered_date DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT CASE WHEN amount >= 1410 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, CASE WHEN shipment_cost >= 78 THEN 'HIGH' ELSE 'LOW' END AS shipment_cost_tier, SORT_ARRAY(COLLECT_SET(status)) AS status_list, ROUND(AVG(amount), 2) AS avg_amount, GROUPING_ID() AS gid FROM latest_match GROUP BY GROUPING SETS ((CASE WHEN amount >= 1410 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN shipment_cost >= 78 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN amount >= 1410 THEN 'PREMIUM' ELSE 'STANDARD' END)) ORDER BY amount_tier DESC;
